[
  {
    "statement": "Chemical methods, particularly herbicides, show variable effectiveness in controlling Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Seven studies found that the herbicide glyphosate reduced Crassula helmsii.",
    "citations": [
      "Seven"
    ]
  },
  {
    "statement": "One study showed a 98% reduction of Crassula helmsii when glyphosate was combined with diquat.",
    "citations": [
      "one"
    ]
  },
  {
    "statement": "Another study achieved an 80% reduction of Crassula helmsii by covering the plant with carpet before a glyphosate treatment.",
    "citations": [
      "one"
    ]
  },
  {
    "statement": "Three out of four studies found that diquat or diquat alginate reduced or eradicated submerged Crassula helmsii.",
    "citations": [
      "Three"
    ]
  },
  {
    "statement": "One study found that diquat or diquat alginate had no effect on Crassula helmsii.",
    "citations": [
      "one"
    ]
  },
  {
    "statement": "Treatment with dichlobenil and terbutryne showed partial reductions in Crassula helmsii biomass in controlled trials.",
    "citations": []
  },
  {
    "statement": "One field study found no effect on Crassula helmsii from dichlobenil.",
    "citations": [
      "one"
    ]
  },
  {
    "statement": "Hydrogen peroxide was found to be ineffective in controlling Crassula helmsii according to one controlled study.",
    "citations": [
      "one"
    ]
  },
  {
    "statement": "Physical methods for controlling Crassula helmsii show different effectiveness results.",
    "citations": []
  },
  {
    "statement": "Lightproof barriers such as black sheeting or carpet strips were effective in five before-and-after studies, eradicating or severely reducing Crassula helmsii cover.",
    "citations": [
      "five"
    ]
  },
  {
    "statement": "Progressive recolonization by Crassula helmsii occurred at two sites after being treated with lightproof barriers.",
    "citations": [
      "two"
    ]
  },
  {
    "statement": "Salt water was highly effective in controlling Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Two replicated controlled container trials and two field trials found that seawater eradicated Crassula helmsii.",
    "citations": [
      "two",
      "two"
    ]
  },
  {
    "statement": "There is currently no evidence available for the effects of manual or mechanical control methods on Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "The combination of physical and chemical methods shows promise for controlling Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "One study found that covering Crassula helmsii with carpet followed by glyphosate treatment killed 80% of the plant.",
    "citations": [
      "one"
    ]
  }
]

[
  {
    "statement": "The most beneficial actions for controlling American bullfrog populations in small ponds include direct removal methods.",
    "citations": []
  },
  {
    "statement": "Double fyke nets have been shown to be effective for catching bullfrog tadpoles in small shallow ponds.",
    "citations": []
  },
  {
    "statement": "Adult bullfrogs can be captured using traps floating on the water surface overnight.",
    "citations": []
  },
  {
    "statement": "Shooting metamorphosed American bullfrogs before reproduction as part of a combination treatment resulted in a significant reduction in the number of recorded adults and juveniles.",
    "citations": []
  },
  {
    "statement": "A chemical treatment of a 10% caffeine solution was effective in killing American bullfrogs.",
    "citations": []
  },
  {
    "statement": "A chemical treatment of a 5% chloroxylenol solution was effective in killing American bullfrogs.",
    "citations": []
  },
  {
    "statement": "A combined chemical treatment of a 4.6% Permethrin solution and a 1% Rotenone solution was effective in killing American bullfrogs.",
    "citations": []
  },
  {
    "statement": "Intensive removal of adult American bullfrogs can result in rapid population rebounds.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence for biological control of invasive aquatic plants using herbivores shows mixed results.",
    "citations": []
  },
  {
    "statement": "A laboratory and field study on floating pennywort found that a South American weevil caused more feeding lesions on the plant than on other plant species.",
    "citations": [
      "1123"
    ]
  },
  {
    "statement": "Field results showed the South American weevil did not reduce floating pennywort biomass.",
    "citations": [
      "1123"
    ]
  },
  {
    "statement": "No evidence was found for using native herbivores to control floating pennywort.",
    "citations": [
      "1124"
    ]
  },
  {
    "statement": "A controlled field study in China found that a flea beetle caused heavy feeding destruction on water primrose.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "The flea beetle in the Chinese study was specific to water primrose and Indian toothcup.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "A study in the USA found that the introduction of flea beetles significantly reduced the abundance of large-flower primrose-willow.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "No evidence was found for using native herbivores to control water primrose.",
    "citations": [
      "1136"
    ]
  },
  {
    "statement": "Evidence for the biological control of parrot's feather shows inconsistent results.",
    "citations": []
  },
  {
    "statement": "A laboratory study in Portugal found that grass carp did not reduce the biomass or cover of parrot's feather.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "Two field studies in Argentina and the USA found that stocking grass carp reduced the biomass or abundance of parrot's feather.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "A field study in South Africa reported reduced growth of parrot's feather following the release of a South American leaf-feeding Lysathia.",
    "citations": [
      "1599"
    ]
  }
]

[
  {
    "statement": "Evidence from controlled studies shows that electrical barriers can be effective in preventing the movement of round gobies.",
    "citations": []
  },
  {
    "statement": "A controlled, replicated field study in the USA found that an electrical barrier prevented movement of round gobies across the barrier.",
    "citations": []
  },
  {
    "statement": "Increasing electrical pulse duration and voltage increased the effectiveness of the electrical barrier.",
    "citations": []
  },
  {
    "statement": "Changing salinity levels is another control method with demonstrated effectiveness.",
    "citations": []
  },
  {
    "statement": "A replicated, controlled laboratory study in Canada found 100% mortality of round gobies within 48 hours of exposure to water of 30% salinity.",
    "citations": []
  },
  {
    "statement": "No evidence was captured from systematic journal and report searches for several other control methods examined, including biological control, habitat manipulation, netting, trapping with lures, UV radiation, changing pH, and increasing carbon dioxide concentrations.",
    "citations": []
  },
  {
    "statement": "The absence of evidence means that certain control methods have not been directly and quantitatively tested in studies.",
    "citations": []
  },
  {
    "statement": "It is not possible to assess the effectiveness or potential harmful impacts of untested control methods based on the available evidence.",
    "citations": []
  }
]

[
  {
    "statement": "Multiple control methods are available for invasive Procambarus crayfish populations.",
    "citations": []
  },
  {
    "statement": "Physical barriers using concrete dams specifically designed to prevent crayfish from crawling over the dams have proven effective at containing upstream population spread.",
    "citations": [
      "1037"
    ]
  },
  {
    "statement": "Trapping and removal using food-baited traps with tinned meat was more effective than using pheromone baits.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Food-baited traps using tinned meat caught over half of all trapped crayfish.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Biological control using predators showed that eels reduced crayfish populations in two Italian studies.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Pike also predated red swamp crayfish in a French study.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Chemical control using pyrethrum Pyblast at a 0.05 mg/l concentration killed crayfish.",
    "citations": [
      "1036"
    ]
  },
  {
    "statement": "The application of pyrethrum Pyblast to drained burrows was ineffective.",
    "citations": [
      "1036"
    ]
  },
  {
    "statement": "Sterilization of male crayfish through X-ray exposure reduced offspring production by 43% in laboratory studies.",
    "citations": [
      "1032"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of removing food sources to control crayfish populations.",
    "citations": [
      "1033"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of draining waterways to control crayfish populations.",
    "citations": [
      "1034"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of electrofishing to control crayfish populations.",
    "citations": [
      "1035"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of relocating vulnerable native species as a management strategy for invasive crayfish.",
    "citations": [
      "1038"
    ]
  }
]

[
  {
    "statement": "Several alternative methods to chemical control have shown effectiveness for managing invasive Asian clam populations in industrial water systems.",
    "citations": []
  },
  {
    "statement": "Mechanical removal has proven highly effective for managing Asian clam populations.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "Suction dredging can reduce Asian clam densities by 96% within sediment over two weeks.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "The reduction in Asian clam densities caused by suction dredging can persist for a year.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "Various dredge types have shown effectiveness in managing Asian clam populations, achieving biomass reductions of 74-95% and density reductions of 65-95%.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "For industrial water systems, combining mechanical removal with regular cleaning of industrial pipes and adding sand filters are effective methods for permanently removing or reducing Asian clam numbers.",
    "citations": [
      "1119"
    ]
  },
  {
    "statement": "Temperature manipulation is a viable approach for managing Asian clam populations.",
    "citations": [
      "1116"
    ]
  },
  {
    "statement": "Controlled studies show that water temperatures of 36°C or higher kill Asian clams within or after four days.",
    "citations": [
      "1116"
    ]
  },
  {
    "statement": "Salinity adjustment has demonstrated 100% mortality when Asian clams are exposed to high salinities of 18-34‰.",
    "citations": [
      "1115"
    ]
  },
  {
    "statement": "Oxygen reduction appears to be an ineffective method for managing Asian clam populations.",
    "citations": [
      "1113"
    ]
  },
  {
    "statement": "Studies indicate Asian clams are resistant to extremely low oxygen levels regardless of temperature or immersion duration.",
    "citations": [
      "1113"
    ]
  }
]

[
  {
    "statement": "Several factors influence the success of physical removal for invasive plants that can regenerate from fragments.",
    "citations": []
  },
  {
    "statement": "For water primrose, studies found that hand pulling and raking failed to reduce abundance in some cases.",
    "citations": [
      "1138"
    ]
  },
  {
    "statement": "Hand-pulling water primrose from pond margins successfully eradicated a smaller population.",
    "citations": [
      "1138"
    ]
  },
  {
    "statement": "A combination approach using glyphosate herbicide followed by mechanical removal for water primrose achieved a 75% kill rate.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "For skunk cabbage, annual physical removal over five years successfully removed an entire stock of recently established plants.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "Manual removal was effective for small outbreaks of small-growing skunk cabbage plants.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "Twice-yearly full removal of skunk cabbage over four years still required large numbers of plants to be removed annually.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "For floating pennywort, a two-week physical removal program resulted in growth exceeding removal rates.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Mechanical digger removal plus monthly hand picking of floating pennywort greatly reduced coverage, but it did not achieve complete eradication.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Population size, plant age, frequency of removal, and use of combination treatments are key factors influencing the success of physical removal for invasive plants.",
    "citations": []
  }
]

[
  {
    "statement": "Based on laboratory studies, exposure to parasites is one of the most effective actions for controlling invasive Ponto-Caspian gammarids.",
    "citations": []
  },
  {
    "statement": "An introduced parasitic mould reduced shrimp populations.",
    "citations": []
  },
  {
    "statement": "Chemical treatments such as iodine solution, acetic acid, Virkon S, and sodium hypochlorite killed killer shrimp.",
    "citations": []
  },
  {
    "statement": "Changing salinity is an effective action for controlling invasive Ponto-Caspian gammarids.",
    "citations": []
  },
  {
    "statement": "Increased salinity killed the majority of shrimp within five hours.",
    "citations": []
  },
  {
    "statement": "Dewatering the habitat of invasive Ponto-Caspian gammarids is an effective control action.",
    "citations": []
  },
  {
    "statement": "Lowering water levels in sand killed three species of gammarids.",
    "citations": []
  },
  {
    "statement": "Behavioral control using chemical cues from predatory fish or carbonated water is an effective action for controlling invasive Ponto-Caspian gammarids.",
    "citations": []
  },
  {
    "statement": "Changing water pH is one of the least effective actions for controlling invasive Ponto-Caspian gammarids.",
    "citations": []
  },
  {
    "statement": "Changing water pH did not kill killer shrimp.",
    "citations": []
  },
  {
    "statement": "Certain chemicals like methanol, citric acid, urea, hydrogen peroxide, and sucrose were not effective at killing killer shrimp.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of biological control using predatory fish.",
    "citations": []
  },
  {
    "statement": "No evidence was found for controlling invasive Ponto-Caspian gammarids by exposure to disease-causing organisms.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of ballast water exchange as a control method.",
    "citations": []
  },
  {
    "statement": "No evidence was found for the effectiveness of cleaning equipment as a control method.",
    "citations": []
  }
]

[
  {
    "statement": "Based on available evidence, 2,4-D appears to be more effective than diquat and glyphosate for controlling parrot's feather.",
    "citations": []
  },
  {
    "statement": "One laboratory study in Brazil found that 2,4-D led to a greater reduction in the growth of parrot's feather compared to diquat, glyphosate, and imazapyr.",
    "citations": [
      "1606"
    ]
  },
  {
    "statement": "Both 2,4-D and diquat showed effectiveness in laboratory studies.",
    "citations": []
  },
  {
    "statement": "Field studies in Portugal demonstrated that 2,4-D amine reduced parrot's feather biomass.",
    "citations": [
      "1606",
      "1680"
    ]
  },
  {
    "statement": "Diquat application did not reduce parrot's feather growth in field conditions.",
    "citations": [
      "1606",
      "1680"
    ]
  },
  {
    "statement": "One laboratory study and one field study in Portugal reported reduced parrot's feather biomass after treatment with glyphosate.",
    "citations": [
      "1699"
    ]
  },
  {
    "statement": "The combined application of 2,4-D and MCPA was found to completely eliminate parrot's feather in a field study in Portugal.",
    "citations": [
      "1606"
    ]
  },
  {
    "statement": "Using 2,4-D and MCPA in combination suggests enhanced effectiveness for controlling parrot's feather.",
    "citations": [
      "1606"
    ]
  }
]

[
  {
    "statement": "The documented evidence for using native predators to control invasive American bullfrogs and Procambarus crayfish in North American freshwater systems shows promising but limited results.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study conducted in Belgium found that introducing northern pike led to a strong decline in bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "Two replicated, controlled studies in Italy demonstrated that eels fed on red swamp crayfish and reduced the crayfish population size.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "One replicated, controlled study from France in 2001 found that pike predated red swamp crayfish.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "The action of simply removing or controlling non-native crayfish was found to have no documented evidence for effects on amphibian populations.",
